DO $$ DECLARE n integer; BEGIN INSERT INTO auth.users(id,instance_id,aud,role,email,created_at,updated_at) VALUES ('123e4567-e89b-42d3-a456-426614174091','00000000-0000-0000-0000-000000000000','authenticated','authenticated','lmf-retention@example.invalid',now(),now()); INSERT INTO public.lmf_reference_sessions(id,owner_id,model_ref,model_sha256,created_at,expires_at) VALUES ('123e4567-e89b-42d3-a456-426614174092','123e4567-e89b-42d3-a456-426614174091','/data/circuit-templates/12v-starting-system-v2.json',repeat('a',64),now()-interval '3 hours',now()-interval '2 hours'),('123e4567-e89b-42d3-a456-426614174093','123e4567-e89b-42d3-a456-426614174091','/data/circuit-templates/12v-starting-system-v2.json',repeat('a',64),now(),now()+interval '2 hours'); INSERT INTO public.lmf_reference_events(session_id,owner_id,sequence_number,payload,event_hash,event_signature) VALUES ('123e4567-e89b-42d3-a456-426614174092','123e4567-e89b-42d3-a456-426614174091',1,'{}',repeat('b',64),repeat('c',64)); n:=lmf_private.purge_expired_reference_sessions(1); IF n<>1 THEN RAISE EXCEPTION 'purge count mismatch'; END IF; IF EXISTS(SELECT 1 FROM public.lmf_reference_events) THEN RAISE EXCEPTION 'cascade failed'; END IF; IF (SELECT count(*) FROM public.lmf_reference_sessions)<>1 THEN RAISE EXCEPTION 'active session lost'; END IF; n:=lmf_private.purge_expired_reference_sessions(1); IF n<>0 THEN RAISE EXCEPTION 'purge not idempotent'; END IF; END $$;